<header class="site-header"><a class="brand" href="./">${_e}<span>home<span class="brand-light">studio</span></span></a><nav class="page-nav" aria-label="Pages"><a href="./">Simulator</a><a href="./design.html" aria-current="page">Design proposal</a></nav><span class="local-tag"><i></i> On your device</span></header>
